using DSWI_T1_1.Data; using DSWI_T1_1.Repositories.Interfaces; using DSWI_T1_1.Repositories.Implementations; using DSWI_T1_1.Services.Interfaces; using DSWI_T1_1.Services.Implementations; using Microsoft.EntityFrameworkCore;
var builder=WebApplication.CreateBuilder(args); builder.Services.AddControllersWithViews(); builder.Services.AddDbContext<ClinicaDbContext>(o=>o.UseSqlServer(builder.Configuration.GetConnectionString("ClinicaDB")));
builder.Services.AddScoped<IPacienteRepository,PacienteRepository>(); builder.Services.AddScoped<ICitaRepository,CitaRepository>(); builder.Services.AddScoped<IPacienteService,PacienteService>(); builder.Services.AddScoped<ICitaService,CitaService>();
var app=builder.Build(); if(!app.Environment.IsDevelopment()){app.UseExceptionHandler("/Home/Error");app.UseHsts();} app.UseHttpsRedirection();app.UseStaticFiles();app.UseRouting();app.UseAuthorization();app.MapControllerRoute("default","{controller=Home}/{action=Index}/{id?}");app.Run();